<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title><?= esc($titulo) ?></title><style>body{margin:0;padding:30px;background:#eee;font:16px Arial;color:#111}.ticket{max-width:720px;margin:auto;background:#fff;border:2px dashed #222;border-radius:16px;overflow:hidden}.head{padding:28px;color:#fff;background:linear-gradient(135deg,#24285b,#654ee8)}.head h1{margin:8px 0;font-size:34px}.body{display:grid;grid-template-columns:1fr 210px;gap:25px;padding:28px}.body p{margin:8px 0}.code{display:grid;place-items:center;padding:18px;border:2px solid #111;text-align:center;word-break:break-all}.code b{font-size:22px;letter-spacing:2px}.status{font-weight:bold;text-transform:uppercase}.actions{text-align:center;margin:22px}@media print{body{padding:0;background:#fff}.actions{display:none}.ticket{border-color:#000}}@media(max-width:600px){.body{grid-template-columns:1fr}}</style></head><body><article class="ticket"><div class="head"><small>TicketFlow · <?= esc($entrada['venta_codigo']) ?></small><h1><?= esc($entrada['evento_nombre']) ?></h1><span><?= esc($entrada['tipo_nombre']) ?></span></div><div class="body"><div><p><b>Fecha:</b> <?= esc(date('d/m/Y H:i', strtotime($entrada['fecha_inicio']))) ?></p><p><b>Lugar:</b> <?= esc($entrada['recinto'] . ', ' . $entrada['ciudad']) ?></p><p><b>Titular:</b> <?= esc($entrada['titular_nombre'] ?: $entrada['cliente_nombre']) ?></p><p class="status">Estado: <?= esc($entrada['estado']) ?></p></div><div class="code"><small>Código de acceso</small><b><?= esc($entrada['codigo']) ?></b><small>Presenta este código en el ingreso</small></div></div></article><div class="actions"><button onclick="window.print()">Imprimir entrada</button></div></body></html>
